func parseErrorBody(data []byte) (string, map[string]any) {
	var eb errorBody
	if err := json.Unmarshal(data, &eb); err == nil && eb.Message != "" {
		return eb.Message, eb.Detail
	}
	if len(data) == 0 {
		return "handler error", nil
	}
	return string(data), nil
}

