	}

	msg.Header.Set(TraceparentHeader, tc.FormatTraceparent())
	msg.Header.Set(TraceIDHeader, tc.TraceID)
	msg.Header.Set(SpanIDHeader, tc.SpanID)
	if tc.ParentSpanID != "" {
		msg.Header.Set(ParentSpanHeader, tc.ParentSpanID)
	}
}

